def _shorten(text: str, lo: int = 22, hi: int = 42) -> str:
    text = re.sub(r"\s+", "", text)
    text = text.rstrip("。；;，,")
    if len(text) > hi:
        text = text[: hi - 1] + "…"
    if len(text) < lo and not text.endswith("已完成"):
        # 不硬凑「推进落地」运维腔
        pass
    return text if text else "数据任务"
